// Quote images – scroll parallax + saturation reveal
(() => {
  const CONFIG = {
    start: 'top bottom', // 0% when trigger top hits viewport bottom
    end: 'bottom top', // 100% when trigger bottom hits viewport top
    scrub: true, // set to e.g. 0.5 for a slightly smoothed feel
    ease: 'none',
  };

  const SATURATION = {
    trigger: '25% center', // fire when trigger center hits viewport center
    duration: 0.6, // seconds, both directions
    ease: 'power2.out', // both directions
    from: 'saturate(0)',
    to: 'saturate(1)',
    desaturateOnLeaveBack: true, // animate back to 0% when scrolling up past the trigger
    targetInnerImg: true, // false = animate the [data-quote-image] div itself
  };

  const images = document.querySelectorAll('[data-quote-image]');
  if (!images.length) return;

  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  images.forEach((img) => {
    const wrapper = img.closest('[data-quote-trigger]');
    if (!wrapper) return;

    const satTarget = SATURATION.targetInnerImg ? img.querySelector('img') || img : img;

    if (reducedMotion) {
      gsap.set(satTarget, { filter: SATURATION.to });
      return;
    }

    const direction = img.getAttribute('data-quote-image'); // 'left' | 'right'
    const travel = () => wrapper.clientHeight - img.offsetHeight;

    gsap.to(img, {
      y: () => (direction === 'left' ? travel() : -travel()),
      ease: CONFIG.ease,
      scrollTrigger: {
        trigger: wrapper,
        start: CONFIG.start,
        end: CONFIG.end,
        scrub: CONFIG.scrub,
        invalidateOnRefresh: true,
      },
    });

    gsap.set(satTarget, { filter: SATURATION.from });

    const saturate = (value) =>
      gsap.to(satTarget, {
        filter: value,
        duration: SATURATION.duration,
        ease: SATURATION.ease,
        overwrite: 'auto',
      });

    ScrollTrigger.create({
      trigger: wrapper,
      start: SATURATION.trigger,
      onEnter: () => saturate(SATURATION.to),
      onLeaveBack: () => {
        if (SATURATION.desaturateOnLeaveBack) saturate(SATURATION.from);
      },
    });
  });

  // Lazy-loaded images can change wrapper/image height after init
  document.querySelectorAll('[data-quote-image] img').forEach((el) => {
    if (!el.complete) {
      el.addEventListener('load', () => ScrollTrigger.refresh(), { once: true });
    }
  });
})();


